import{_ as d,C as i,o,c as s,a6 as t,b as c,w as a,a as n,E as l,ae as h}from"./chunks/framework.BHBQfcoO.js";const f=JSON.parse('{"title":"Layout View Architecture","description":"","frontmatter":{},"headers":[],"relativePath":"architecture/layout-view.md","filePath":"architecture/layout-view.md"}'),p={name:"architecture/layout-view.md"};function g(u,e,m,v,y,w){const r=i("Mermaid");return o(),s("div",null,[e[1]||(e[1]=t('<h1 id="layout-view-architecture" tabindex="-1">Layout View Architecture <a class="header-anchor" href="#layout-view-architecture" aria-label="Permalink to &quot;Layout View Architecture&quot;">​</a></h1><p>The <strong>Layout View</strong> (<code>custom:lcards-layout-view</code>) is a <code>LovelaceViewElement</code> that renders a CSS Grid and provides an in-view WYSIWYG editor. This page covers how it&#39;s built and the non-obvious constraints behind its design.</p><p>All code lives in <code>src/views/</code>:</p><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td><code>lcards-layout-view.js</code></td><td>The view element: renders the grid, mounts HA-provided cards, owns config + persistence, manages the editor overlay.</td></tr><tr><td><code>lcards-grid-edit-overlay.js</code></td><td>The in-view editor chrome (Layout mode): track handles, headers, area overlays, toolbars, settings panels.</td></tr><tr><td><code>layout-grid-utils.js</code></td><td>Pure, DOM-free functions: track-list parsing, 2D area manipulation, area-settings reconciliation.</td></tr><tr><td><code>layout-render.js</code></td><td>Shared render helpers (<code>buildGridStyle</code>, <code>applyCardPlacement</code>, <code>renderAreaSurfaces</code>, <code>resolveColorValue</code>) used by both the view and the card.</td></tr><tr><td><code>layout-edit-dialogs.js</code></td><td>Shared <code>ha-dialog</code> confirmation helper (destructive actions).</td></tr></tbody></table><p>The <strong>card</strong> version (<code>custom:lcards-layout-card</code>) reuses all of the above:</p><table tabindex="0"><thead><tr><th>File</th><th>Role</th></tr></thead><tbody><tr><td><code>cards/lcards-layout-card.js</code></td><td>Container card: renders the same grid, builds its own children as <code>hui-card</code> wrappers (so native Visibility works), propagates hass. Read-only on the dashboard.</td></tr><tr><td><code>editor/cards/lcards-layout-card-editor.js</code></td><td>The card&#39;s GUI editor: a thin launcher that opens the Layout Studio and relays its <code>config-changed</code> to HA.</td></tr><tr><td><code>editor/dialogs/lcards-layout-studio-dialog.js</code></td><td>Full-screen studio: a single live preview + grid overlay on a large canvas, a Layout tab (global settings), and a tab per card with an inline <code>hui-card-element-editor</code> + placement.</td></tr></tbody></table><hr><h2 id="component-model" tabindex="-1">Component model <a class="header-anchor" href="#component-model" aria-label="Permalink to &quot;Component model&quot;">​</a></h2>',8)),(o(),c(h,null,{default:a(()=>[l(r,{id:"mermaid-108",class:"mermaid",graph:"graph%20TB%0A%20%20%20%20subgraph%20View%5B%22lcards-layout-view%20(LovelaceViewElement)%22%5D%0A%20%20%20%20%20%20%20%20Grid%5B%22%23grid-root%5Cnreal%20CSS%20grid%20%2B%20mounted%20cards%22%5D%0A%20%20%20%20%20%20%20%20Surfaces%5B%22area%20surfaces%5Cn(layout.areas%20backings)%22%5D%0A%20%20%20%20%20%20%20%20Save%5B%22_saveViewConfig%5Cnserialized%20lovelace%20save%22%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20Overlay%5B%22lcards-grid-edit-overlay%20(Layout%20mode)%22%5D%0A%20%20%20%20%20%20%20%20Ghost%5B%22%23ghost-grid%5Cn(measurement%20source)%22%5D%0A%20%20%20%20%20%20%20%20Chrome%5B%22headers%20%C2%B7%20handles%20%C2%B7%20area%20overlays%20%C2%B7%20panels%22%5D%0A%20%20%20%20end%0A%20%20%20%20HA%5B%22HA%3A%20lovelace%20%2F%20hass%20%2F%20pre-built%20card%20elements%22%5D%0A%0A%20%20%20%20HA%20--%3E%7C%22set%20lovelace%20%2F%20hass%20%2F%20cards%22%7C%20View%0A%20%20%20%20View%20--%3E%7C%22createElement%20%2B%20props%20(imperative)%22%7C%20Overlay%0A%20%20%20%20Overlay%20--%3E%7C%22grid-state-changed%20%C2%B7%20area-*%20%C2%B7%20add-card%20%C2%B7%20layout-settings%22%7C%20View%0A%20%20%20%20View%20--%3E%20Save%20--%3E%7C%22lovelace.saveConfig%22%7C%20HA%0A%0A%20%20%20%20style%20View%20fill%3A%231c3c55%2Cstroke%3A%2337a6d1%2Ccolor%3A%23eee%0A%20%20%20%20style%20Overlay%20fill%3A%232f3749%2Cstroke%3A%2352596e%2Ccolor%3A%23eee%0A"})]),fallback:a(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t('<p>The view holds the parsed grid state (<code>_columns</code>, <code>_rows</code>, <code>_areas</code>, <code>_gap</code>) and the raw <code>_config</code>. The overlay is <strong>stateless about persistence</strong>: it edits a copy of the grid passed in as properties and emits events; the view is the single writer.</p><hr><h2 id="imperative-overlay-creation-scoped-registry-constraint" tabindex="-1">Imperative overlay creation (scoped-registry constraint) <a class="header-anchor" href="#imperative-overlay-creation-scoped-registry-constraint" aria-label="Permalink to &quot;Imperative overlay creation (scoped-registry constraint)&quot;">​</a></h2><p>The view does <strong>not</strong> put <code>&lt;lcards-grid-edit-overlay&gt;</code> in its Lit template. HA builds custom view elements through a <em>scoped</em> custom-element registry (<code>create-view-element.ts</code>). A globally-registered element nested via a Lit template tag inside that view throws:</p><blockquote><p><code>Failed to construct &#39;HTMLElement&#39;: This instance is already constructed</code></p></blockquote><p>So <code>_syncEditOverlay()</code> (called from <code>updated()</code>) creates the overlay with <code>document.createElement(&#39;lcards-grid-edit-overlay&#39;)</code> (the <strong>global</strong> registry), wires events with <code>addEventListener</code>, sets state via properties, and appends it to <code>renderRoot</code>. It is removed when leaving Layout mode and on disconnect.</p><p>The <strong>layout card</strong> uses the same imperative pattern, but inside the <strong>Layout Studio</strong> dialog rather than HA&#39;s cramped card-edit dialog: the studio creates a single preview card <em>and</em> a single grid overlay via <code>document.createElement</code> on a large canvas. Because the studio owns one of each for its lifetime (and is destroyed on close), the duplicate-overlay/alignment problems of in-dialog editing don&#39;t arise. Editing needs <strong>no edit-mode detection</strong> and no nested-path <code>saveConfig</code>; overlay events recompute a working config and the studio fires <code>config-changed</code>, which the card&#39;s GUI editor relays to HA. New cards use HA&#39;s <code>hui-card-picker</code>; each card is edited inline with <code>hui-card-element-editor</code> in its tab.</p><hr><h2 id="the-ghost-grid-measurement-pattern" tabindex="-1">The ghost-grid measurement pattern <a class="header-anchor" href="#the-ghost-grid-measurement-pattern" aria-label="Permalink to &quot;The ghost-grid measurement pattern&quot;">​</a></h2><p>The editor chrome is <strong>not</strong> laid out with CSS grid. Instead the overlay renders a transparent <code>#ghost-grid</code> with the same <code>grid-template-*</code>, and after each render <code>_measure()</code> (in a <code>requestAnimationFrame</code>) calls <code>getBoundingClientRect()</code> on every ghost cell to build <code>_cells[r][c]</code> pixel rects. All chrome (column/row headers, resize handles, area overlays, cell targets, popovers) is then <strong>positioned absolutely</strong> from those measurements via <code>_positionElements()</code>.</p><p>This avoids the offset bug that occurs when header/ruler tracks consume grid space. A <code>ResizeObserver</code> on the overlay re-measures whenever the view resizes (e.g. the HA sidebar expands/collapses), keeping the chrome aligned with the real grid.</p><h3 id="header-gutter" tabindex="-1">Header gutter <a class="header-anchor" href="#header-gutter" aria-label="Permalink to &quot;Header gutter&quot;">​</a></h3><p><code>GRID_EDIT_GUTTER</code> (28px, from <code>layout-grid-utils.js</code>) does <strong>not</strong> pad <code>#grid-root</code>; both the view and the card call <code>buildGridStyle(..., { withGutter: false })</code>, so the grid keeps its natural size in Layout mode. The overlay imports the same constant as <code>HEADER_OVERLAP</code> and instead sizes/positions its column/row headers, add-row/add-col buttons, and corner controls to float over the first <code>HEADER_OVERLAP</code>px of the real grid. <code>buildGridStyle</code>&#39;s <code>withGutter</code> option still exists (reserves <code>padding-top</code>/<code>padding-left</code>) but neither call site passes <code>true</code> today.</p><h3 id="unified-pointer-dispatch" tabindex="-1">Unified pointer dispatch <a class="header-anchor" href="#unified-pointer-dispatch" aria-label="Permalink to &quot;Unified pointer dispatch&quot;">​</a></h3><p><code>connectedCallback</code> binds a single <code>pointermove</code>/<code>pointerup</code> pair to the overlay element (not <code>document</code>; shadow-DOM boundaries and <code>setPointerCapture</code> on cells both break there). <code>_onAnyPointerMove</code>/<code>_onAnyPointerUp</code> route to whichever drag is active: track resize, header reorder, rubber-band area selection, toolbar drag, or the area-settings-panel drag.</p><hr><h2 id="card-placement-per-area-surfaces" tabindex="-1">Card placement &amp; per-area surfaces <a class="header-anchor" href="#card-placement-per-area-surfaces" aria-label="Permalink to &quot;Card placement &amp; per-area surfaces&quot;">​</a></h2><p><code>_placeCards()</code> rebuilds <code>#grid-root</code> whenever cards or layout change:</p><ol><li><strong>Area surfaces</strong> (<code>renderAreaSurfaces()</code>, from <code>layout-render.js</code>): for each entry in <code>layout.areas</code>, a non-interactive <code>.area-surface</code> div is appended first (so cards paint above it by DOM order), styled by <code>applyAreaSurfaceStyle()</code>. <code>theme:</code> tokens in colors are resolved via <code>window.lcards.core.themeManager.resolver</code>.</li><li><strong>Cards</strong>: each HA-provided card element gets placement applied by <code>applyCardPlacement(gridItem, cardEl, viewLayout, cardMargin, cardOverflow, areaSettings)</code> (also from <code>layout-render.js</code>).</li></ol><p><strong>Precedence:</strong> global (<code>card_margin</code> / <code>card_overflow</code>) → per-area (<code>layout.areas[name]</code>) → per-card (<code>view_layout</code>). Grid placement and alignment land on the <em>grid item</em> (the card, or its edit-mode wrapper); <code>overflow</code> lands on the card so content clips regardless of the wrapper.</p><p>In Card mode each card is wrapped in a <code>.card-edit-wrap</code> (the grid item) carrying edit / placement / remove handles; empty areas get an <strong>Add card</strong> placeholder.</p><p>Cards are <strong>always placed</strong>; per-card visibility is not the view&#39;s concern. HA hands the view <code>hui-card</code> wrappers, which evaluate each card&#39;s native <strong>Visibility</strong> conditions and hide themselves reactively. The view therefore implements no <code>view_layout.show</code> handling (unlike upstream layout-card, whose card mode bypasses the <code>hui-card</code> wrapper).</p><hr><h2 id="visibility-driven-row-sizing" tabindex="-1">Visibility-driven row sizing <a class="header-anchor" href="#visibility-driven-row-sizing" aria-label="Permalink to &quot;Visibility-driven row sizing&quot;">​</a></h2><p>HA&#39;s <code>hui-card</code> wrapper hides cards by setting <code>display: none</code>. In a standard CSS Grid, a <code>display: none</code> item does not contribute to track sizing, so a row with only hidden cards collapses to <code>0px</code> naturally. In practice, HA&#39;s layout context does not provide the grid engine with a definite available block-size, so <code>fr</code> tracks expand to the max-content of their items rather than filling the remaining space. This makes <code>minmax(0,auto)</code> tracks collapse correctly but <code>1fr</code> tracks wrong.</p><p>The view solves this entirely in JS:</p><h3 id="baserows-and-visibilityrows" tabindex="-1"><code>_baseRows</code> and <code>_visibilityRows</code> <a class="header-anchor" href="#baserows-and-visibilityrows" aria-label="Permalink to &quot;`_baseRows` and `_visibilityRows`&quot;">​</a></h3><p><code>_baseRows</code> holds the row tracks as parsed from config (never modified at runtime). After every card placement, <code>_collectVisibilityRows()</code> scans the placed cards for a non-empty <code>visibility</code> array, any condition type or shape; conditions are <strong>not</strong> parsed. For each card with a definite <code>layout.height</code> and a <code>grid-area</code> it records <code>{ rowIndex, cardEl, targetHeight }</code> in <code>_visibilityRows</code>.</p><p>The view deliberately never evaluates conditions itself. HA&#39;s <code>hui-card</code> owns that (since HA 2026.10 stateful conditions are evaluated by core over a <code>subscribe_condition</code> websocket subscription, and HA&#39;s Visibility editor rewrites <code>state</code>/<code>numeric_state</code> conditions from lovelace <code>entity</code> shape into core <code>entity_id</code> shape). The view reads the outcome: <code>hui-card</code> toggles its <code>hidden</code> attribute and fires a bubbling, composed <code>card-visibility-changed</code> event, the same signal <code>hui-section</code> uses.</p><h3 id="applyvisibilityrowheights" tabindex="-1"><code>_applyVisibilityRowHeights()</code> <a class="header-anchor" href="#applyvisibilityrowheights" aria-label="Permalink to &quot;`_applyVisibilityRowHeights()`&quot;">​</a></h3><p>Called from: end of <code>_placeCards()</code>, every <code>updated()</code> (after Lit renders), and (rAF-debounced via <code>_scheduleRowHeights()</code>) every <code>card-visibility-changed</code> event and every host resize. It is <strong>not</strong> called from <code>set hass()</code>: entity updates reach it only through hui-card&#39;s visibility event, so ordinary state changes cost no layout reads.</p><ol><li><strong>Build candidate rows</strong>: start from <code>_baseRows</code>; a visibility row gets <code>targetHeight</code> if the view is in edit mode or <strong>any</strong> of its registered cards is not <code>hidden</code>, otherwise <code>&#39;0px&#39;</code>.</li><li><strong>Identify <code>fr</code> tracks</strong>: locate all <code>Nfr</code> tracks in the candidate rows.</li><li><strong>Resolve non-fr sizes</strong>: temporarily write the rows with every <code>fr</code> replaced by <code>0px</code> and force a reflow (<code>getComputedStyle</code>), so the browser evaluates all <code>clamp()</code>, <code>vh</code>, <code>px</code>, and <code>min()</code>/<code>max()</code> tracks to their actual pixel sizes.</li><li><strong>Compute fr allocation</strong>: <code>frSpace = hostHeight - sum(non-fr rows) - sum(gaps)</code>. This is exact regardless of what the CSS Grid engine would have done.</li><li><strong>Final write</strong>: replace every <code>Nfr</code> track with <code>round(frSpace × N / totalFR)px</code> and write <code>grid.style.gridTemplateRows</code> directly (bypassing Lit to avoid a re-render feedback loop).</li></ol><p>Nested <code>hui-card</code>s (inside an MSD control, <code>lcards-layout-card</code> child, or elbow symbiont) never reach the view&#39;s listener: the enclosing top-level <code>hui-card</code> catches and stops <code>card-visibility-changed</code> from its own inner element.</p><h3 id="resizeobserver" tabindex="-1"><code>ResizeObserver</code> <a class="header-anchor" href="#resizeobserver" aria-label="Permalink to &quot;`ResizeObserver`&quot;">​</a></h3><p>A <code>ResizeObserver</code> on the host element (created in <code>connectedCallback</code>, torn down in <code>disconnectedCallback</code>) fires <code>_applyVisibilityRowHeights()</code> via a <code>requestAnimationFrame</code> debounce whenever the host&#39;s bounding box changes: window resize, HA sidebar toggle, devtools open/close. This keeps row allocations correct across all viewport changes without polling.</p><hr><h2 id="persistence-event-flow" tabindex="-1">Persistence &amp; event flow <a class="header-anchor" href="#persistence-event-flow" aria-label="Permalink to &quot;Persistence &amp; event flow&quot;">​</a></h2><p>HA hands the view three inputs via setters: <code>hass</code>, <code>lovelace</code>, and <code>cards</code> (pre-built card elements). The view never pushes config to HA except through one funnel.</p><h3 id="serialized-saves" tabindex="-1">Serialized saves <a class="header-anchor" href="#serialized-saves" aria-label="Permalink to &quot;Serialized saves&quot;">​</a></h3><p><code>_saveViewConfig()</code> coalesces concurrent edits into a single in-flight chain and <strong>always rebases on the latest <code>lovelace.config</code></strong> at the moment each write runs. This prevents the <em>&quot;Dashboard updated in another session&quot;</em> error that stale-snapshot saves caused when several edits (resize commit, area create, card add) fired in quick succession.</p><h3 id="card-add-edit-interception" tabindex="-1">Card add / edit interception <a class="header-anchor" href="#card-add-edit-interception" aria-label="Permalink to &quot;Card add / edit interception&quot;">​</a></h3><p>HA&#39;s create-card and edit-card dialogs save <strong>directly via <code>lovelace.saveConfig()</code></strong>, bypassing events. The view&#39;s <code>lovelace</code> setter diffs <code>prevCards</code> against the new cards:</p><ul><li><strong>Add</strong> (length grew) with a pending area → injects <code>view_layout.grid-area</code> into the new card, then re-saves.</li><li><strong>Edit</strong> (same length) with a pending edit → restores <code>view_layout</code> if HA stripped it.</li></ul><h3 id="area-lifecycle-reconciliation" tabindex="-1">Area lifecycle reconciliation <a class="header-anchor" href="#area-lifecycle-reconciliation" aria-label="Permalink to &quot;Area lifecycle reconciliation&quot;">​</a></h3><p>Per-area settings (<code>layout.areas</code>) are keyed by area name, so they must track renames and deletions:</p><ul><li><strong>Rename</strong>: the overlay emits <code>area-renamed {from,to}</code> <em>before</em> <code>grid-state-changed</code>; the view migrates the key (<code>renameAreaSettings</code>) without saving, and the following grid-state save persists it.</li><li><strong>Delete / track removal</strong>: <code>_onGridStateChanged</code> prunes orphans via <code>pruneAreaSettings</code> against the current area names.</li></ul><p>All of these route back through <code>_saveViewConfig</code>.</p><hr><h2 id="drop-in-compatibility" tabindex="-1">Drop-in compatibility <a class="header-anchor" href="#drop-in-compatibility" aria-label="Permalink to &quot;Drop-in compatibility&quot;">​</a></h2><p>The schema mirrors <code>custom:grid-layout</code> (lovelace-layout-card): <code>layout.{grid-template-*, grid-gap, height, margin, padding, card_margin, card_overflow, mediaquery}</code> plus flat <code>cards[]</code> with <code>view_layout</code>. The grid renderer is ~50 lines of CSS plumbing replicated trivially; the value-add is the visual editor. Two intentional differences:</p><ul><li><strong><code>layout.areas</code></strong> (surface decoration) is an LCARdS-only, optional, additive namespace that <code>custom:grid-layout</code> ignores, so configs stay portable in both directions.</li><li><strong><code>view_layout.show</code> is not implemented.</strong> Per-card conditions defer to HA&#39;s native card Visibility (<code>hui-card</code>); a migrated config using <code>show</code> ignores that key.</li></ul>',51))])}const A=d(p,[["render",g]]);export{f as __pageData,A as default};
